// Teléfono a formato internacional (+52 + 10 dígitos para México; otros países ya con su lada).
function e164(raw) {
  const s = String(raw || '').replace(/^whatsapp:/, '');
  const d = s.replace(/\D/g, '');
  if (d.length === 10) return '+52' + d;
  if (d.length === 13 && d.startsWith('521')) return '+52' + d.slice(3);
  if (s.trim().startsWith('+') && d.length >= 11) return '+' + d;
  if (d.length === 12 && d.startsWith('52')) return '+' + d;
  return null;
}
// Cuerpo application/x-www-form-urlencoded para Twilio. (El código de n8n 2.x no trae URLSearchParams.)
const formulario = (campos) => Object.entries(campos).filter(([, v]) => v !== undefined && v !== null && v !== '').map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v))).join('&');
const twilioUrl = (cfg, c) => 'https://api.twilio.com/2010-04-01/Accounts/' + (c.twilioAccountSid || cfg.twilioAccountSid) + '/Messages.json';

// CONFIGURACIÓN (lo único que se edita). Sirve a uno o a varios negocios: un renglón por negocio en «clientes».
// - Las REGLAS (a quién, cuándo, cuántos intentos y el texto) las define cada negocio en Reymen:
//   CRM → Contactos → Configurar seguimientos. Reymen decide a quién le toca; este flujo solo lo envía.
// - orgId y llave: Admin de Reymen → Clientes → (cliente) → botón de webhook. La llave es secreta: no exportes ni
//   compartas este flujo con ella puesta. El token de Twilio va en la credencial «Twilio» de n8n (no aquí).
// - PLANTILLAS: WhatsApp exige plantilla APROBADA para escribirle a alguien que no te ha escrito en las últimas 24 h
//   (el caso normal de un seguimiento). Se busca en este orden y se usa la primera que tenga contentSid:
//     1) la del negocio para esa regla (por su nombre en Reymen), 2) la del negocio «default»,
//     3) la general para esa regla, 4) la general «default».
//   Sin ninguna, se manda el texto de la regla de Reymen, que WhatsApp solo entrega dentro de las 24 h.
//   variables = qué dato va en {{1}}, {{2}}…: contactName (primer nombre), fullName, businessName, ruleName, attemptNumber.
//   Si cada número está en una cuenta de WhatsApp Business distinta, cada negocio necesita sus plantillas aprobadas
//   en su cuenta (aunque el texto sea igual): ponlas en su renglón.
// - modoPrueba: true = solo arma y muestra los mensajes, sin enviar ni avisar a Reymen. Se puede poner por negocio
//   (por ejemplo, un negocio nuevo en prueba mientras los demás ya envían).
const cfg = {
  reymenUrl: 'https://app.reymen.mx',
  twilioAccountSid: 'ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
  horaInicio: 9,
  horaFin: 20,
  zonaHoraria: 'America/Monterrey',
  maxPorCorrida: 40,       // por negocio
  modoPrueba: true,
  plantillas: {
    default: { contentSid: '', variables: ['contactName'] },
    // 'Recontacto semanal': { contentSid: 'HX...', variables: ['contactName', 'businessName'] },
  },
  clientes: [
    { nombre: 'Villa Gardenia', orgId: 'PEGA_AQUI_EL_ID_DE_LA_ORGANIZACION', llave: 'PEGA_AQUI_LA_LLAVE_DE_CONEXION', whatsapp: '+528100000000' },
    // Ejemplo de otro negocio con horario, prueba y plantillas propias (borra o copia este renglón):
    // { nombre: 'Otro negocio', orgId: '...', llave: '...', whatsapp: '+528100000001', horaInicio: 10, horaFin: 19, modoPrueba: true,
    //   plantillas: { default: { contentSid: 'HX...', variables: ['contactName', 'businessName'] } } },
  ],
};

const primerNombre = (n) => String(n || '').trim().split(/\s+/)[0] || '';
const conSid = (p) => (p && p.contentSid ? p : null);
const out = [];
const problemas = [];
for (const c of cfg.clientes) {
  if (!c.orgId || c.orgId.startsWith('PEGA_AQUI')) continue;
  const tz = c.zonaHoraria || cfg.zonaHoraria;
  const hora = Number(new Intl.DateTimeFormat('es-MX', { hour: 'numeric', hour12: false, timeZone: tz }).format(new Date()));
  if (hora < (c.horaInicio ?? cfg.horaInicio) || hora >= (c.horaFin ?? cfg.horaFin)) continue; // fuera de su horario
  let rows;
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: cfg.reymenUrl + '/api/v1/leads/due-followups', qs: { orgId: c.orgId }, headers: { 'X-Api-Key': c.llave }, json: true, timeout: 20000 });
    rows = res.data || [];
  } catch (e) {
    problemas.push(c.nombre + ': ' + (e.message || 'error al consultar Reymen')); // un negocio con error no detiene a los demás
    continue;
  }
  const propias = c.plantillas || {};
  let n = 0;
  for (const r of rows) {
    if (r.channel !== 'whatsapp') continue;
    const to = e164(r.contactPhone);
    if (!to) continue;
    const datos = { contactName: primerNombre(r.contactName) || 'hola', fullName: r.contactName || '', businessName: c.nombre || '', ruleName: r.ruleName || '', attemptNumber: String(r.attemptNumber || '') };
    const plantilla = conSid(propias[r.ruleName]) || conSid(propias.default) || conSid((cfg.plantillas || {})[r.ruleName]) || conSid((cfg.plantillas || {}).default);
    const text = String(r.template || '').replace(/\{\{\s*contactName\s*\}\}/g, primerNombre(r.contactName)).trim();
    const campos = { From: 'whatsapp:' + e164(c.whatsapp), To: 'whatsapp:' + to };
    if (plantilla) {
      const vars = {};
      (plantilla.variables || ['contactName']).forEach((k, i) => { vars[String(i + 1)] = String(datos[k] || '').trim() || '-'; });
      campos.ContentSid = plantilla.contentSid;
      campos.ContentVariables = JSON.stringify(vars);
    } else {
      campos.Body = text;
    }
    out.push({ json: {
      negocio: c.nombre, orgId: c.orgId, llave: c.llave, reymenUrl: cfg.reymenUrl,
      leadId: r.leadId, ruleId: r.ruleId, regla: r.ruleName, attemptNumber: r.attemptNumber,
      contacto: r.contactName, to, plantilla: plantilla ? plantilla.contentSid : '(texto de la regla)', text,
      form: formulario(campos), twilioUrl: twilioUrl(cfg, c),
      modoPrueba: (c.modoPrueba ?? cfg.modoPrueba) === true,
    } });
    if (++n >= (c.maxPorCorrida || cfg.maxPorCorrida)) break;
  }
}
if (problemas.length) console.log('Seguimientos: ' + problemas.join(' | '));
return out;

// Por cada mensaje que Twilio aceptó (trae «sid»), avisa a Reymen —firmado con la llave de ESE negocio— para que
// cuente el intento. Los que fallaron no se avisan: Reymen los vuelve a ofrecer en la próxima corrida.
// Requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto en el entorno de n8n.
const crypto = require('crypto');
const out = [];
$input.all().forEach((res, i) => {
  const sent = $('Preparar mensajes').itemMatching(i).json;
  if (!sent || !res.json.sid) return;
  const body = JSON.stringify({ leadId: sent.leadId, ruleId: sent.ruleId });
  const ts = String(Date.now());
  const sig = 'sha256=' + crypto.createHmac('sha256', sent.llave).update(ts + '.' + body).digest('hex');
  out.push({ json: {
    url: sent.reymenUrl + '/api/webhooks/n8n/followup-sent',
    orgId: sent.orgId, body, ts, sig,
    // Id estable por intento: si este aviso se repite, Reymen lo cuenta una sola vez.
    eventId: 'followup:' + sent.leadId + ':' + sent.ruleId + ':' + sent.attemptNumber,
    negocio: sent.negocio, contacto: sent.contacto, twilioSid: res.json.sid,
  } });
});
return out;
